import {sb,hasSupabase,prefs,savePrefs,defaultPrefs,sound,toast,openModal,closeModal,esc,dateLabel,today,levelFor,levelProgress,demoData,saveDemo,id} from './core.js';

const state={user:null,profile:{name:'Jogador'},tasks:[],events:[],habits:[],habitLogs:[],workouts:[],study:[],xpLog:[],xp:0,settings:prefs(),route:'inicio',taskFilter:'pending',calDate:new Date(),calMode:'month',notices:[],busy:false};
const routes={inicio:'Início',tarefas:'Tarefas',calendario:'Calendário',fisico:'Atividade física',estudos:'Programação e estudos',habitos:'Hábitos e rotina',evolucao:'Minha evolução',missoes:'Missões',conquistas:'Conquistas',recompensas:'Recompensas',perfil:'Perfil',configuracoes:'Configurações'};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmtDate=d=>d?new Date(d).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}):'Sem prazo';
const localDateTime=d=>{const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,16)};
const localDate=d=>d?localDateTime(d).slice(0,10):'';
const reminderOptions=[[0,'No horário exato'],[5,'5 minutos antes'],[10,'10 minutos antes'],[15,'15 minutos antes'],[30,'30 minutos antes'],[60,'1 hora antes'],[1440,'1 dia antes'],[-1,'Sem notificação']];
function getXP(){return state.user?state.xp:demoData().xp||0}
function getTasks(){return state.user?state.tasks:demoData().tasks}
function addNotice(title,body=''){state.notices.unshift({id:id(),title,body,at:new Date().toISOString()});state.notices=state.notices.slice(0,20);$('#notice-dot').classList.remove('hidden')}
function updateHeader(){const p=levelProgress(getXP());$('#side-name').textContent=state.profile.name||state.user?.email?.split('@')[0]||'Jogador';$('#side-level').textContent=`Nível ${p.level} · ${getXP()} XP`;$('#top-name').textContent=state.profile.name||'Jogador';$('#auth-button').classList.toggle('hidden',!!state.user);$('#user-chip').classList.toggle('hidden',!state.user);$('#connection-dot').style.background=hasSupabase?(state.user?'var(--green)':'var(--amber)'):'var(--amber)';$('#connection-label').textContent=state.user?'Conta conectada':hasSupabase?'Entre para sincronizar':'Modo local • configure Supabase';}
function data(){return state.user?state:demoData()}
async function loadData(){
 if(!state.user){const d=demoData();Object.assign(state,{...d,profile:{name:d.profile?.name||'Jogador'},settings:prefs()});return}
 const uid=state.user.id;
 const [pr,t,ev,ha,hl,wo,st,xp,sett]=await Promise.all([
 sb.from('lu_profiles').select('*').eq('user_id',uid).maybeSingle(),
 sb.from('lu_tasks').select('*').eq('user_id',uid).order('due_at',{ascending:true,nullsFirst:false}),
 sb.from('lu_events').select('*').eq('user_id',uid).order('starts_at'),
 sb.from('lu_habits').select('*').eq('user_id',uid).order('created_at'),
 sb.from('lu_habit_logs').select('*').eq('user_id',uid),
 sb.from('lu_workouts').select('*').eq('user_id',uid).order('created_at',{ascending:false}),
 sb.from('lu_study_sessions').select('*').eq('user_id',uid).order('created_at',{ascending:false}),
 sb.from('lu_xp_events').select('*').eq('user_id',uid).order('created_at',{ascending:false}),
 sb.from('lu_settings').select('*').eq('user_id',uid).maybeSingle()
 ]);
 for(const r of [pr,t,ev,ha,hl,wo,st,xp,sett])if(r.error)throw r.error;
 state.profile={name:pr.data?.player_name||state.user.email?.split('@')[0]||'Jogador'};
 state.tasks=t.data||[];state.events=ev.data||[];state.habits=ha.data||[];state.habitLogs=hl.data||[];state.workouts=wo.data||[];state.study=st.data||[];state.xpLog=xp.data||[];state.xp=state.xpLog.reduce((s,x)=>s+x.amount,0);
 state.settings={...prefs(),...(sett.data?.settings||{})};savePrefs(state.settings);
}
async function refresh(){try{await loadData();updateHeader();render()}catch(e){toast('Não foi possível carregar os dados: '+(e.message||'erro de conexão'),'error',6500)}}
async function saveProfile(name){if(state.user){const {error}=await sb.from('lu_profiles').upsert({user_id:state.user.id,player_name:name,updated_at:new Date().toISOString()});if(error)throw error;state.profile.name=name}else{const d=demoData();d.profile={name};saveDemo(d);state.profile.name=name}updateHeader()}
async function persistSettings(){savePrefs(state.settings);if(state.user){const {error}=await sb.from('lu_settings').upsert({user_id:state.user.id,settings:state.settings,updated_at:new Date().toISOString()});if(error)throw error}}
async function insert(table,row){if(state.user){
  let payload={...row,user_id:state.user.id};
  const optionalTaskColumns=['spent_minutes','due_date_only','reminder_minutes','reminder_sent_at'];
  state.taskSchemaWarning=null;
  for(let attempt=0;attempt<=optionalTaskColumns.length;attempt++){
   const {data,error}=await sb.from(table).insert(payload).select().single();
   if(!error)return data;
   const message=String(error.message||'')+' '+String(error.details||'');
   const isSchemaError=['PGRST204','PGRST205','42703'].includes(String(error.code||''))||/schema cache|column .* does not exist|could not find the .* column/i.test(message);
   const missing=table==='lu_tasks'&&isSchemaError?optionalTaskColumns.find(col=>Object.prototype.hasOwnProperty.call(payload,col)&&message.toLowerCase().includes(col)):null;
   if(!missing)throw error;
   delete payload[missing];
   state.taskSchemaWarning=state.taskSchemaWarning||[];
   state.taskSchemaWarning.push(missing);
  }
  throw new Error('Não foi possível salvar a tarefa por incompatibilidade do esquema do banco.');
 }
 const d=demoData();const key=({lu_tasks:'tasks',lu_events:'events',lu_habits:'habits',lu_habit_logs:'habitLogs',lu_workouts:'workouts',lu_study_sessions:'study',lu_english_results:'exerciseResults',lu_vocabulary:'vocab'})[table];if(!key)throw Error('Esta ação exige uma conta conectada.');const item={...row,id:id(),created_at:new Date().toISOString()};d[key]=d[key]||[];d[key].push(item);saveDemo(d);return item}
async function updateRow(table,rowId,patch){if(state.user){const {error}=await sb.from(table).update(patch).eq('id',rowId).eq('user_id',state.user.id);if(error)throw error;return}
 const d=demoData(),key=({lu_tasks:'tasks',lu_events:'events',lu_habits:'habits'})[table];const item=(d[key]||[]).find(x=>x.id===rowId);if(!item)throw Error('Item não encontrado');Object.assign(item,patch);saveDemo(d)}
async function deleteRow(table,rowId){if(state.user){const {error}=await sb.from(table).delete().eq('id',rowId).eq('user_id',state.user.id);if(error)throw error;return}
 const d=demoData(),key=({lu_tasks:'tasks',lu_events:'events',lu_habits:'habits'})[table];d[key]=(d[key]||[]).filter(x=>x.id!==rowId);saveDemo(d)}
async function award(type,sourceId,reason,amount=10){if(state.user){const {data,error}=await sb.rpc('lu_award_activity_xp',{p_source_type:type,p_source_id:sourceId,p_reason:reason,p_amount:amount});if(error)throw error;state.xp=data.total_xp;return data.awarded}
 const d=demoData();if(!d.xpLog)d.xpLog=[];if(d.xpLog.some(x=>x.source_id===sourceId&&x.source_type===type))return 0;d.xp+=amount;d.xpLog.push({id:id(),source_type:type,source_id:sourceId,amount,reason,created_at:new Date().toISOString()});saveDemo(d);state.xp=d.xp;return amount}
async function completeTask(taskId){if(state.user){const {data,error}=await sb.rpc('lu_complete_task',{p_task_id:taskId});if(error)throw error;state.xp=data.total_xp;if(data.awarded)addNotice('XP recebido',`+${data.awarded} XP por concluir uma tarefa`);return data.awarded}
 const d=demoData(),t=(d.tasks||[]).find(x=>x.id===taskId);if(!t||t.completed_at)return 0;if(!d.xpLog)d.xpLog=[];t.completed_at=new Date().toISOString();d.xp=(d.xp||0)+20;d.xpLog.push({id:id(),source_type:'task',source_id:t.id,amount:20,reason:'Tarefa concluída',created_at:new Date().toISOString()});saveDemo(d);state.xp=d.xp;return 20}
function setRoute(route){if(!routes[route])route='inicio';state.route=route;location.hash=route;$('#page-title').textContent=routes[route];$$('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));$('#sidebar').classList.remove('open');render()}
function head(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">PLAYER SYSTEM / ${esc(state.route)}</div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`}
function cardHead(title,sub='',right=''){return `<div class="card-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function empty(title,desc,button=''){return `<div class="empty"><strong>${title}</strong>${desc}${button?`<div style="margin-top:13px">${button}</div>`:''}</div>`}
function taskRow(t){const done=!!t.completed_at;return `<div class="task-row ${done?'done':''}"><input class="check" type="checkbox" data-action="complete-task" data-id="${t.id}" ${done?'checked disabled':''} aria-label="Concluir ${esc(t.title)}"><div class="task-copy"><strong>${esc(t.title)}</strong><small>${esc(({general:'Geral',english:'Inglês',study:'Estudos',fitness:'Atividade física',habit:'Hábito',personal:'Pessoal'})[t.category]||t.category||'Geral')} · ${t.due_at?(t.due_date_only?new Date(t.due_at).toLocaleDateString('pt-BR'):dateLabel(t.due_at)):'Sem prazo'} ${t.estimated_minutes?`· ${t.estimated_minutes} min`:''}</small></div><span class="tag ${t.priority==='high'?'red-tag':t.priority==='low'?'':'amber-tag'}">${t.priority==='high'?'Alta':t.priority==='low'?'Baixa':'Média'}</span><button class="icon-button" data-action="edit-task" data-id="${t.id}" title="Editar tarefa">✎</button><button class="icon-button" data-action="delete-task" data-id="${t.id}" title="Excluir tarefa">×</button></div>`}
function renderHome(){const tasks=getTasks(),pending=tasks.filter(t=>!t.completed_at),done=tasks.filter(t=>t.completed_at),xp=getXP(),lp=levelProgress(xp),upcoming=pending.filter(t=>t.due_at).sort((a,b)=>new Date(a.due_at)-new Date(b.due_at)).slice(0,4);const completedToday=done.filter(t=>t.completed_at?.slice(0,10)===today()).length;const totalStudy=(state.study||[]).reduce((s,x)=>s+(+x.duration_minutes||0),0);
return `${head(`Olá, ${esc(state.profile.name||'jogador')} 👋`,'Seu próximo nível é construído com pequenas ações consistentes.',`<button class="btn btn-primary" data-action="new-task">＋ Nova tarefa</button>`)}
<div class="hero"><div class="hero-main"><div class="eyebrow">SUA JORNADA COMEÇA AQUI</div><h1>Um passo de cada vez.<br><span class="red">Um nível de cada vez.</span></h1><p>Transforme o que você quer aprender em missões concretas. Escolha uma tarefa e comece a ganhar XP.</p><div class="hero-actions"><button class="btn btn-primary" data-route="tarefas">Ver minhas tarefas ↗</button><button class="btn btn-outline" data-route="tarefas">Organizar tarefas</button></div></div><div class="card level-card"><div class="eyebrow">NÍVEL ATUAL</div><div class="level-orb"><div><strong>${lp.level}</strong><span>LEVEL</span></div></div><div class="row-between" style="width:100%"><span class="muted small">XP total</span><b>${xp.toLocaleString('pt-BR')} XP</b></div><div class="progress"><span style="width:${lp.pct}%"></span></div><div class="row-between" style="width:100%"><small class="muted">${lp.current} XP neste nível</small><small class="muted">${lp.needed} XP para subir</small></div></div></div>
<div class="grid grid-4"><div class="card stat-card"><div class="stat-icon">☑</div><div class="stat-label">Tarefas pendentes</div><div class="stat-value">${pending.length}</div><div class="stat-note">${completedToday} concluída(s) hoje</div></div><div class="card stat-card"><div class="stat-icon">⚑</div><div class="stat-label">Tarefas concluídas</div><div class="stat-value">${done.length}</div><div class="stat-note">Seu progresso registrado</div></div><div class="card stat-card"><div class="stat-icon">✧</div><div class="stat-label">XP conquistado hoje</div><div class="stat-value">${(state.xpLog||[]).filter(x=>x.created_at?.slice(0,10)===today()).reduce((n,x)=>n+x.amount,0)}</div><div class="stat-note">Somente XP registrado</div></div><div class="card stat-card"><div class="stat-icon">⌘</div><div class="stat-label">Tempo de estudo</div><div class="stat-value">${Math.floor(totalStudy/60)}<small style="font-size:14px;color:var(--muted)">h ${totalStudy%60}m</small></div><div class="stat-note">Somente sessões registradas</div></div></div>
<div class="grid grid-2 section-gap"><section class="card">${cardHead('Missão em andamento','Uma lista curta ajuda a começar.',`<a class="small red" href="#tarefas" data-route="tarefas">Ver todas ↗</a>`)}${pending.length?`<div class="list">${pending.slice(0,4).map(taskRow).join('')}</div>`:empty('Tudo em dia!','Adicione uma tarefa para começar a ganhar XP.',`<button class="btn btn-primary" data-action="new-task">Criar tarefa</button>`)}</section><section class="card">${cardHead('Próximos prazos','Atividades com data definida.')}${upcoming.length?`<div class="list">${upcoming.map(t=>`<div class="metric-line"><div class="metric-icon">◷</div><div class="metric-copy"><b>${esc(t.title)}</b><small>${dateLabel(t.due_at)}</small></div><span class="tag ${new Date(t.due_at)<new Date()?'red-tag':''}">${new Date(t.due_at)<new Date()?'Atrasada':'Agendada'}</span></div>`).join('')}</div>`:empty('Sem prazos próximos','Quando uma tarefa tiver data limite, ela aparecerá aqui.')}</section></div>
<div class="grid grid-3 section-gap"><section class="card">${cardHead('Organize seu progresso','Tarefas de qualquer matéria ou área.')}<p class="muted small">Crie tarefas de Inglês, Matemática, Programação ou categorias personalizadas.</p><button class="btn btn-outline" data-route="tarefas">Ver tarefas ↗</button></section><section class="card">${cardHead('Corpo em movimento','Atividade física sem pressão.')}<p class="muted small">${state.workouts.length} atividade(s) registrada(s). Descanso também faz parte.</p><button class="btn btn-outline" data-route="fisico">Registrar atividade ↗</button></section><section class="card">${cardHead('Seu histórico','Acompanhe o que realmente fez.')}<p class="muted small">${state.xpLog?.length||0} recompensa(s) de XP no histórico disponível.</p><button class="btn btn-outline" data-route="evolucao">Ver evolução ↗</button></section></div>`}
function taskForm(t={}){
 openModal(`<div class="eyebrow">QUEST LOG</div><h2>${t.id?'Editar tarefa':'Nova tarefa'}</h2><p>Organize o próximo passo. Os campos com * são obrigatórios.</p><div id="task-form-error" role="alert" class="small" style="display:none;color:var(--red);margin:10px 0"></div><form id="task-form" class="form-grid"><div class="field full"><label for="task-title">Nome da tarefa *</label><input id="task-title" name="title" required maxlength="140" value="${esc(t.title||'')}" placeholder="Ex.: estudar arrays em JavaScript"></div><div class="field full"><label for="task-desc">Descrição</label><textarea id="task-desc" name="description" maxlength="2000" placeholder="Detalhes opcionais">${esc(t.description||'')}</textarea></div><div class="field"><label>Matéria ou categoria</label><input name="category" list="task-categories" maxlength="60" value="${esc(({general:'Geral',english:'Inglês',study:'Estudos',fitness:'Atividade física',habit:'Hábito',personal:'Pessoal'})[t.category]||t.category||'Geral')}" placeholder="Ex.: Inglês, Matemática"><datalist id="task-categories"><option value="Geral"><option value="Inglês"><option value="Matemática"><option value="Programação"><option value="Banco de Dados"><option value="Português"><option value="Estudos"><option value="Pessoal"><option value="Atividade física"></datalist></div><div class="field"><label>Prioridade</label><select name="priority">${[['low','Baixa'],['medium','Média'],['high','Alta']].map(([v,l])=>`<option value="${v}" ${(t.priority||'medium')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Data de vencimento</label><input type="date" name="due_date" value="${t.due_at?localDate(t.due_at):''}"></div><div class="field"><label>Horário (opcional)</label><input type="time" name="due_time" step="60" value="${t.due_at&&!t.due_date_only?localDateTime(t.due_at).slice(11,16):''}"><small class="muted">Deixe vazio para registrar somente a data.</small></div><div class="field"><label>Lembrete</label><select name="reminder_minutes">${reminderOptions.map(([v,l])=>`<option value="${v}" ${Number(t.reminder_minutes??state.settings.reminderMinutes)===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Tempo dedicado (min)</label><input type="number" min="0" max="1440" name="spent_minutes" value="${t.spent_minutes??''}" placeholder="Registrar quando souber"></div><div class="field"><label>Tempo estimado (min)</label><input type="number" min="1" max="1440" name="estimated_minutes" value="${t.estimated_minutes||''}" placeholder="Ex.: 25"></div><div class="form-actions field full"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${t.id?'Salvar alterações':'Criar tarefa'}</button></div><input type="hidden" name="id" value="${t.id||''}"></form>`);
 const form=$('#task-form');
 if(!form)return;
 form.addEventListener('submit',async event=>{
  event.preventDefault();
  if(form.dataset.saving==='true')return;
  const button=form.querySelector('button[type="submit"]');
  const errorBox=$('#task-form-error');
  form.dataset.saving='true';
  if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='Salvando…'}
  if(errorBox){errorBox.style.display='none';errorBox.textContent=''}
  try{await handleTaskForm(form)}
  catch(err){
   const message=taskSaveError(err);
   if(errorBox){errorBox.textContent=message;errorBox.style.display='block'}
   toast(message,'error',8000);
  }
  finally{
   form.dataset.saving='false';
   if(button&&button.isConnected){button.disabled=false;button.textContent=button.dataset.originalText||'Criar tarefa'}
  }
 });
}
function renderTasks(){const all=getTasks(),filtered=all.filter(t=>state.taskFilter==='all'?true:state.taskFilter==='done'?!!t.completed_at:state.taskFilter==='overdue'?!t.completed_at&&t.due_at&&new Date(t.due_at)<new Date():!t.completed_at);return `${head('Tarefas','Transforme objetivos grandes em próximos passos executáveis.',`<button class="btn btn-primary" data-action="new-task">＋ Nova tarefa</button>`)}<div class="card"><div class="row-between" style="margin-bottom:15px"><div class="tabs" id="task-tabs">${[['pending','Pendentes'],['all','Todas'],['done','Concluídas'],['overdue','Atrasadas']].map(([v,l])=>`<button data-action="task-filter" data-value="${v}" class="${state.taskFilter===v?'active':''}">${l}</button>`).join('')}</div><span class="muted small">${filtered.length} tarefa(s)</span></div><div class="list">${filtered.length?filtered.sort((a,b)=>Number(!!a.completed_at)-Number(!!b.completed_at)).map(taskRow).join(''):empty('Nenhuma tarefa por aqui','Experimente outro filtro ou crie uma nova tarefa.',`<button class="btn btn-primary" data-action="new-task">＋ Nova tarefa</button>`)}</div></div>`}
function renderCalendar(){const date=new Date(state.calDate),mode=state.calMode;let start,end,days=[];if(mode==='day'){start=new Date(date);start.setHours(0,0,0,0);end=new Date(start);end.setDate(end.getDate()+1);days=[new Date(start)]}else if(mode==='week'){start=new Date(date);start.setDate(start.getDate()-((start.getDay()+6)%7));start.setHours(0,0,0,0);end=new Date(start);end.setDate(end.getDate()+7);for(let i=0;i<7;i++){let d=new Date(start);d.setDate(d.getDate()+i);days.push(d)}}else{start=new Date(date.getFullYear(),date.getMonth(),1);end=new Date(date.getFullYear(),date.getMonth()+1,1);const offset=(start.getDay()+6)%7;start.setDate(start.getDate()-offset);for(let i=0;i<42;i++){let d=new Date(start);d.setDate(d.getDate()+i);days.push(d)}}
const evs=[...state.events.map(e=>({id:e.id,title:e.title,starts_at:e.starts_at,category:e.category,completed_at:e.completed_at,kind:'event'})),...getTasks().filter(t=>t.due_at).map(t=>({id:t.id,title:t.title,starts_at:t.due_at,category:t.category,completed_at:t.completed_at,kind:'task'}))];
const same=(a,b)=>a.toDateString()===b.toDateString();
return `${head('Calendário de missões','Prazos, sessões e compromissos em um só lugar.',`<button class="btn btn-primary" data-action="new-event">＋ Agendar atividade</button>`)}<div class="card"><div class="row-between" style="flex-wrap:wrap;margin-bottom:16px"><div class="row-between" style="gap:8px"><button class="icon-button" data-action="cal-prev">‹</button><h2>${mode==='day'?date.toLocaleDateString('pt-BR',{dateStyle:'full'}):mode==='week'?`${fmtDate(days[0])} — ${fmtDate(days[6])}`:date.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2><button class="icon-button" data-action="cal-next">›</button><button class="btn btn-quiet" data-action="cal-today">Hoje</button></div><div class="tabs">${[['day','Dia'],['week','Semana'],['month','Mês']].map(([v,l])=>`<button data-action="cal-mode" data-value="${v}" class="${mode===v?'active':''}">${l}</button>`).join('')}</div></div>${mode==='month'?`<div class="calendar-grid">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<div class="weekday">${x}</div>`).join('')}${days.map(d=>{const de=evs.filter(e=>same(new Date(e.starts_at),d));return `<div class="calendar-day ${d.getMonth()!==date.getMonth()?'muted-day':''} ${same(d,new Date())?'today':''}" data-action="calendar-day" data-date="${d.toISOString()}"><b>${d.getDate()}</b>${de.slice(0,3).map(e=>`<div class="calendar-event" title="${esc(e.title)}">${esc(e.title)}</div>`).join('')}${de.length>3?`<small class="muted">+${de.length-3}</small>`:''}</div>`}).join('')}</div>`:`<div class="list">${days.map(d=>{const de=evs.filter(e=>same(new Date(e.starts_at),d));return `<div class="day-plan"><b>${d.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'})}</b>${de.length?de.map(e=>`<div class="metric-line"><div class="metric-icon">◷</div><div class="metric-copy"><b>${esc(e.title)}</b><small>${new Date(e.starts_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} · ${esc(e.category||'Geral')}</small></div><span class="tag">${e.completed_at?'Concluída':'Agendada'}</span></div>`).join(''):'<p class="muted small">Nenhuma atividade programada.</p>'}</div>`}).join('')}</div>`}</div>`}
function eventForm(){openModal(`<div class="eyebrow">SCHEDULE</div><h2>Agendar atividade</h2><p>Os eventos do calendário ficam vinculados à sua conta.</p><form id="event-form" class="form-grid"><div class="field full"><label>Nome *</label><input name="title" required maxlength="140" placeholder="Ex.: sessão de programação"></div><div class="field"><label>Categoria</label><select name="category"><option value="general">Geral</option><option value="english">Inglês</option><option value="study">Estudos</option><option value="fitness">Atividade física</option><option value="personal">Pessoal</option></select></div><div class="field"><label>Data *</label><input name="starts_date" type="date" required value="${localDateTime(new Date(Date.now()+3600000)).slice(0,10)}"></div><div class="field"><label>Horário (opcional)</label><input name="starts_time" type="time" step="60" value="${localDateTime(new Date(Date.now()+3600000)).slice(11,16)}"></div><div class="field"><label>Lembrete</label><select name="reminder_minutes">${reminderOptions.map(([v,l])=>`<option value="${v}" ${Number(state.settings.reminderMinutes)===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label>Observações</label><textarea name="notes"></textarea></div><div class="form-actions field full"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancelar</button><button class="btn btn-primary">Agendar</button></div></form>`)}
function renderFitness(){const total=state.workouts.reduce((s,x)=>s+(+x.duration_minutes||0),0);return `${head('Atividade física','Registre movimento de um jeito flexível. Descansar também conta como cuidar de si.',`<button class="btn btn-primary" data-action="new-workout">＋ Registrar atividade</button>`)}<div class="grid grid-3"><div class="card stat-card"><div class="stat-icon">✦</div><div class="stat-label">Atividades registradas</div><div class="stat-value">${state.workouts.length}</div></div><div class="card stat-card"><div class="stat-icon">◷</div><div class="stat-label">Tempo acumulado</div><div class="stat-value">${total}<small style="font-size:13px;color:var(--muted)"> min</small></div></div><div class="card stat-card"><div class="stat-icon">▦</div><div class="stat-label">Nesta semana</div><div class="stat-value">${state.workouts.filter(x=>new Date(x.activity_date)>=new Date(Date.now()-7*86400000)).length}</div></div></div><section class="card section-gap">${cardHead('Histórico de atividades','Modalidades e duração informadas por você.')}${state.workouts.length?`<div class="list">${state.workouts.map(x=>`<div class="metric-line"><div class="metric-icon">✦</div><div class="metric-copy"><b>${esc(x.modality)}</b><small>${fmtDate(x.activity_date)} · ${x.duration_minutes} min ${x.notes?'· '+esc(x.notes):''}</small></div><span class="tag green-tag">Registrada</span></div>`).join('')}</div>`:empty('Nenhuma atividade registrada','Caminhada, alongamento, dança, esporte ou qualquer movimento que faça sentido para você.',`<button class="btn btn-primary" data-action="new-workout">Registrar primeira atividade</button>`)}</section>`}
function workoutForm(){openModal(`<div class="eyebrow">ACTIVITY LOG</div><h2>Registrar atividade</h2><p>Escolha uma atividade adequada à sua rotina e ao seu bem-estar.</p><form id="workout-form" class="form-grid"><div class="field"><label>Modalidade *</label><select name="modality"><option>Caminhada</option><option>Corrida</option><option>Mobilidade</option><option>Alongamento</option><option>Dança</option><option>Esportes</option><option>Treino de força</option><option>Outra</option></select></div><div class="field"><label>Duração (minutos) *</label><input type="number" name="duration_minutes" required min="1" max="600" value="20"></div><div class="field"><label>Data *</label><input type="date" name="activity_date" required value="${today()}"></div><div class="field full"><label>Observações (opcional)</label><textarea name="notes" maxlength="1000" placeholder="Como foi?"></textarea></div><div class="form-actions field full"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancelar</button><button class="btn btn-primary">Salvar atividade</button></div></form>`)}
function renderStudies(){const total=state.study.reduce((s,x)=>s+(+x.duration_minutes||0),0);return `${head('Programação e estudos','Registre sessões, aprendizados e dificuldades — não só horas no relógio.',`<button class="btn btn-primary" data-action="new-study">＋ Registrar sessão</button>`)}<div class="grid grid-3"><div class="card stat-card"><div class="stat-icon">⌘</div><div class="stat-label">Sessões registradas</div><div class="stat-value">${state.study.length}</div></div><div class="card stat-card"><div class="stat-icon">◷</div><div class="stat-label">Tempo de estudo</div><div class="stat-value">${total}<small style="font-size:13px;color:var(--muted)"> min</small></div></div><div class="card stat-card"><div class="stat-icon">✧</div><div class="stat-label">XP recebido</div><div class="stat-value">${state.xpLog.filter(x=>x.source_type==='study').reduce((s,x)=>s+x.amount,0)}</div></div></div><section class="card section-gap">${cardHead('Diário de aprendizagem','Seus registros mais recentes.')}${state.study.length?`<div class="list">${state.study.map(x=>`<div class="metric-line"><div class="metric-icon">⌘</div><div class="metric-copy"><b>${esc(x.subject)}</b><small>${dateLabel(x.created_at)} · ${x.duration_minutes} min${x.learned?' · '+esc(x.learned):''}</small>${x.difficulty?`<small>Dificuldade: ${esc(x.difficulty)}</small>`:''}</div><span class="tag green-tag">+ XP</span></div>`).join('')}</div>`:empty('Seu diário está vazio','Registre o que estudou e o que aprendeu.',`<button class="btn btn-primary" data-action="new-study">Registrar sessão</button>`)}</section>`}
function studyForm(){openModal(`<div class="eyebrow">STUDY SESSION</div><h2>Registrar sessão de estudo</h2><form id="study-form" class="form-grid"><div class="field full"><label>Assunto *</label><input name="subject" required maxlength="140" placeholder="Ex.: fundamentos de banco de dados"></div><div class="field"><label>Duração (minutos) *</label><input name="duration_minutes" type="number" required min="1" max="1440" value="25"></div><div class="field"><label>O que foi mais difícil?</label><input name="difficulty" maxlength="300" placeholder="Opcional"></div><div class="field full"><label>O que aprendeu?</label><textarea name="learned" maxlength="2000" placeholder="Anote um conceito ou exemplo"></textarea></div><div class="form-actions field full"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancelar</button><button class="btn btn-primary">Salvar sessão</button></div></form>`)}
function renderHabits(){const habits=state.habits.filter(x=>!x.archived),logs=state.habitLogs||[],doneToday=logs.filter(x=>x.log_date===today()).length;return `${head('Hábitos e rotina','Consistência é um histórico, não uma sequência perfeita.',`<button class="btn btn-primary" data-action="new-habit">＋ Novo hábito</button>`)}<div class="grid grid-3"><div class="card stat-card"><div class="stat-icon">↻</div><div class="stat-label">Hábitos ativos</div><div class="stat-value">${habits.length}</div></div><div class="card stat-card"><div class="stat-icon">✓</div><div class="stat-label">Concluídos hoje</div><div class="stat-value">${doneToday}</div></div><div class="card stat-card"><div class="stat-icon">◷</div><div class="stat-label">Registros totais</div><div class="stat-value">${logs.length}</div></div></div><section class="card section-gap">${cardHead('Sua rotina','Marque os hábitos que realizou hoje.')}${habits.length?`<div class="list">${habits.map(h=>{const done=logs.some(x=>x.habit_id===h.id&&x.log_date===today());return `<div class="task-row ${done?'done':''}"><input class="check" type="checkbox" data-action="habit-toggle" data-id="${h.id}" ${done?'checked':''}><div class="task-copy"><strong>${esc(h.title)}</strong><small>${h.frequency==='daily'?'Todos os dias':h.frequency==='weekly'?'Semanal':'Dias selecionados'} · ${logs.filter(x=>x.habit_id===h.id).length} registro(s)</small></div><button class="icon-button" data-action="habit-archive" data-id="${h.id}" title="Arquivar">⌑</button></div>`}).join('')}</div>`:empty('Crie seu primeiro hábito','Ex.: ler por 10 minutos, organizar a mesa ou planejar o dia.',`<button class="btn btn-primary" data-action="new-habit">Criar hábito</button>`)}</section>`}
function habitForm(){openModal(`<div class="eyebrow">ROUTINE BUILDER</div><h2>Novo hábito</h2><form id="habit-form" class="form-grid"><div class="field full"><label>Nome do hábito *</label><input name="title" required maxlength="120" placeholder="Ex.: revisar 5 palavras em inglês"></div><div class="field full"><label>Frequência</label><select name="frequency"><option value="daily">Todos os dias</option><option value="weekly">Semanal</option></select></div><div class="form-actions field full"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancelar</button><button class="btn btn-primary">Criar hábito</button></div></form>`)}
function renderEvolution(){
 const xpLog=state.xpLog||[],tasks=getTasks(),period=$('#evolution-period')?.value||'week',category=$('#evolution-category')?.value||'all';
 const now=new Date(),start=new Date(now);if(period==='day')start.setHours(0,0,0,0);else if(period==='week')start.setDate(start.getDate()-6);else if(period==='month')start.setDate(start.getDate()-29);else if(period==='custom'){const raw=$('#evolution-start')?.value;if(raw)start.setTime(new Date(raw+'T00:00:00').getTime());else start.setFullYear(2000)}else start.setFullYear(2000);
 const endDate=$('#evolution-end')?.value?new Date($('#evolution-end').value+'T23:59:59'):now;const inPeriod=x=>{const d=new Date(x||0);return d>=start&&d<=endDate};const filteredXP=xpLog.filter(x=>inPeriod(x.created_at));
 const categoryOf=t=>String(t.category||'general');const categoryXP=x=>{if(category==='all')return true;const task=tasks.find(t=>t.id===x.source_id);return (task?categoryOf(task):x.source_type)===category};
 const shownXP=filteredXP.filter(categoryXP),total=shownXP.reduce((n,x)=>n+(Number(x.amount)||0),0);
 const completed=tasks.filter(t=>t.completed_at&&inPeriod(t.completed_at)&&(category==='all'||categoryOf(t)===category));
 const pending=tasks.filter(t=>!t.completed_at),overdue=pending.filter(t=>t.due_at&&new Date(t.due_at)<now);
 const minutes=tasks.filter(t=>(category==='all'||categoryOf(t)===category)&&inPeriod(t.completed_at||t.updated_at||t.created_at)).reduce((n,t)=>n+(Number(t.spent_minutes)||0),0)+state.study.filter(x=>inPeriod(x.created_at)).reduce((n,x)=>n+(Number(x.duration_minutes)||0),0);
 const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toLocaleDateString('en-CA');days.push({key,label:d.toLocaleDateString('pt-BR',{weekday:'short'}),xp:shownXP.filter(x=>x.created_at&&new Date(x.created_at).toLocaleDateString('en-CA')===key).reduce((n,x)=>n+x.amount,0),tasks:tasks.filter(x=>x.completed_at&&new Date(x.completed_at).toLocaleDateString('en-CA')===key).length})}const max=Math.max(1,...days.map(d=>d.xp));
 const cats=[...new Set(tasks.map(t=>categoryOf(t)))];const label=c=>({'general':'Geral','english':'Inglês','study':'Estudos','fitness':'Atividade física','habit':'Hábito','personal':'Pessoal'})[c]||c;
 const history=shownXP.filter(x=>inPeriod(x.created_at));const activeDays=new Set([...xpLog.map(x=>x.created_at?.slice(0,10)),...tasks.map(t=>t.completed_at?.slice(0,10)),...state.study.map(x=>x.created_at?.slice(0,10))].filter(Boolean));let streak=0;for(let i=0;i<366;i++){const d=new Date();d.setDate(d.getDate()-i);const k=d.toISOString().slice(0,10);if(activeDays.has(k))streak++;else if(i===0)continue;else break}
 return `${head('Minha evolução','Acompanhe XP, esforço e tarefas usando apenas registros reais.')}<div class="filters"><label>Período <select id="evolution-period"><option value="day" ${period==='day'?'selected':''}>Hoje</option><option value="week" ${period==='week'?'selected':''}>7 dias</option><option value="month" ${period==='month'?'selected':''}>30 dias</option><option value="all" ${period==='all'?'selected':''}>Todo o histórico</option><option value="custom" ${period==='custom'?'selected':''}>Personalizado</option></select></label><label>De <input id="evolution-start" type="date" value="${$('#evolution-start')?.value||''}"></label><label>Até <input id="evolution-end" type="date" value="${$('#evolution-end')?.value||today()}"></label><label>Categoria <select id="evolution-category"><option value="all">Todas</option>${cats.map(c=>`<option value="${esc(c)}" ${category===c?'selected':''}>${esc(label(c))}</option>`).join('')}</select></label></div>
 <div class="grid grid-4"><div class="card stat-card"><div class="stat-label">XP no período</div><div class="stat-value">${total}</div></div><div class="card stat-card"><div class="stat-label">Tarefas concluídas</div><div class="stat-value">${completed.length}</div></div><div class="card stat-card"><div class="stat-label">Pendentes / atrasadas</div><div class="stat-value">${pending.length} / ${overdue.length}</div></div><div class="card stat-card"><div class="stat-label">Tempo registrado</div><div class="stat-value">${Math.floor(minutes/60)}<small style="font-size:13px;color:var(--muted)">h ${minutes%60}m</small></div></div><div class="card stat-card"><div class="stat-label">Sequência atual</div><div class="stat-value">${streak}<small style="font-size:13px;color:var(--muted)"> dia(s)</small></div></div></div>
 <div class="grid grid-2 section-gap"><section class="card">${cardHead('XP por dia · últimos 7 dias','Barras calculadas a partir do histórico de recompensas.')} ${xpLog.length?`<div class="chart">${days.map(d=>`<div class="bar-wrap"><span class="bar-value">${d.xp||''}</span><div class="bar" title="${d.xp} XP" style="height:${Math.max(2,d.xp/max*120)}px"></div><span class="bar-label">${d.label}</span></div>`).join('')}</div>`:empty('Ainda não há dados de XP','As barras aparecerão após recompensas reais.')}</section><section class="card">${cardHead('Esforço por categoria','Tempo registrado manualmente nas tarefas e sessões de estudo.')}${cats.length?cats.map(c=>{const m=tasks.filter(t=>categoryOf(t)===c).reduce((n,t)=>n+(Number(t.spent_minutes)||0),0);return `<div class="metric-line"><div class="metric-copy"><b>${esc(label(c))}</b><small>${tasks.filter(t=>categoryOf(t)===c&&t.completed_at).length} tarefa(s) concluída(s)</small></div><strong>${m} min</strong></div>`}).join(''):empty('Sem categorias ainda','Crie tarefas para começar a acompanhar áreas.')}</section></div>
 <section class="card section-gap">${cardHead('Histórico detalhado',`${history.length} evento(s) de XP no período`)}${history.length?`<div class="list">${history.map(x=>{const t=tasks.find(t=>t.id===x.source_id);return `<div class="metric-line"><div class="metric-icon">✧</div><div class="metric-copy"><b>${esc(x.reason||x.source_type)}</b><small>${dateLabel(x.created_at)} · ${esc(t?label(categoryOf(t)):x.source_type)}${t?' · '+esc(t.title):''}</small></div><span class="tag green-tag">+${x.amount} XP</span></div>`}).join('')}</div>`:empty('Nenhum evento neste filtro','Tente outro período ou categoria.')}</section>`}

const achievementDefs=[['first-task','☑','Primeiro passo','Conclua sua primeira tarefa.'],['study-first','⌘','Mente ativa','Registre sua primeira sessão de estudo.'],['fitness-first','✦','Em movimento','Registre uma atividade física.'],['level-2','◆','Subindo de nível','Alcance o nível 2.']];
function renderAchievements(){const tasks=getTasks(),unlocked=new Set();if(tasks.some(x=>x.completed_at))unlocked.add('first-task');if(state.study.length)unlocked.add('study-first');if(state.workouts.length)unlocked.add('fitness-first');if(levelFor(getXP())>=2)unlocked.add('level-2');return `${head('Conquistas','Marcos desbloqueados pelas suas ações reais.')}<div class="badge-grid">${achievementDefs.map(([k,icon,title,desc])=>`<div class="achievement ${unlocked.has(k)?'':'locked'}"><div class="ach-icon">${icon}</div><b>${title}</b><small>${unlocked.has(k)?'Desbloqueada':desc}</small></div>`).join('')}</div><section class="card section-gap">${cardHead('Missões','Objetivos simples para ajudar a começar.')}${[['Concluir uma tarefa',tasks.some(x=>x.completed_at)],['Criar uma tarefa',tasks.length>0],['Registrar uma sessão de estudo',state.study.length>0],['Registrar uma atividade física',state.workouts.length>0]].map(([label,done])=>`<div class="metric-line"><div class="metric-icon">${done?'✓':'⚑'}</div><div class="metric-copy"><b>${label}</b><small>${done?'Objetivo concluído':'Conclua a ação para cumprir a missão'}</small></div><span class="tag ${done?'green-tag':'amber-tag'}">${done?'Concluída':'Em andamento'}</span></div>`).join('')}</section>`}
function renderMissions(){return `${head('Missões','Objetivos com condições claras. Sem penalidades por descansar.')}<div class="grid grid-2">${[['Primeiro passo','Conclua uma tarefa',getTasks().some(t=>t.completed_at),'Tarefas'],['Organização em andamento','Crie uma tarefa',getTasks().length>0,'Tarefas'],['Mente em treino','Registre uma sessão de estudo',state.study.length>0,'Estudos'],['Movimento registrado','Registre uma atividade física',state.workouts.length>0,'Atividade física']].map(([title,desc,done,route])=>`<section class="card"><div class="row-between"><span class="tag ${done?'green-tag':'red-tag'}">${done?'Concluída':'Missão'}</span><span class="muted">⚑</span></div><h2 style="margin:14px 0 7px">${title}</h2><p class="muted">${desc}</p><div class="progress" style="margin:14px 0"><span style="width:${done?100:0}%"></span></div><button class="btn ${done?'btn-quiet':'btn-outline'}" data-route="${route==='Tarefas'?'tarefas':route==='Estudos'?'estudos':'fisico'}">${done?'Ver atividade':'Ir para atividade'} ↗</button></section>`).join('')}</div>`}
function renderRewards(){const log=state.xpLog||[];return `${head('Recompensas','Cada recompensa tem uma origem no seu histórico.')}<div class="hero"><section class="hero-main"><div class="eyebrow">XP WALLET</div><h1>${getXP()} <span class="red">XP</span></h1><p>XP concedido por ações registradas. A fórmula de nível usa a raiz quadrada do XP acumulado.</p><div class="hero-actions"><button class="btn btn-primary" data-route="tarefas">Ganhar XP com tarefas</button></div></section><section class="card">${cardHead('Como funciona','Progressão transparente')}<p class="muted">Tarefa concluída: +20 XP. Sessão de estudo, atividade física ou hábito: recompensa pequena por registro, limitada por ação única.</p><div class="divider"></div><b>Nível atual: ${levelFor(getXP())}</b><p class="muted small">XP não pode ser alterado diretamente pelo painel quando conectado ao Supabase.</p></section></div><section class="card">${cardHead('Histórico de XP',`${log.length} evento(s)`)}${log.length?`<div class="list">${log.map(x=>`<div class="metric-line"><div class="metric-icon">✧</div><div class="metric-copy"><b>${esc(x.reason||x.source_type)}</b><small>${dateLabel(x.created_at)}</small></div><span class="tag green-tag">+${x.amount} XP</span></div>`).join('')}</div>`:empty('Nenhuma recompensa ainda','Conclua uma tarefa ou registre uma atividade válida para ganhar XP.')}</section>`}
function renderProfile(){const lp=levelProgress(getXP());return `${head('Perfil do jogador','Sua identidade e seus marcos dentro do LEVEL UP.')}<div class="grid grid-2"><section class="card"><div style="display:flex;gap:15px;align-items:center"><div class="avatar" style="width:62px;height:62px;font-size:27px">◆</div><div><div class="eyebrow">PLAYER PROFILE</div><h2 style="font-size:24px;margin:4px 0">${esc(state.profile.name)}</h2><span class="tag">Nível ${lp.level}</span></div></div><div class="divider"></div><div class="row-between"><span class="muted">XP total</span><b>${getXP()}</b></div><div class="progress" style="margin:10px 0"><span style="width:${lp.pct}%"></span></div><small class="muted">${lp.current} / ${lp.needed} XP para o próximo nível</small><div class="divider"></div><div class="row-between"><span class="muted">Conta</span><b>${state.user?esc(state.user.email):'Modo local (sem autenticação)'}</b></div></section><section class="card">${cardHead('Editar nome de jogador','Use um nome que seja fácil de reconhecer.')}<form id="profile-form"><div class="field"><label>Nome de jogador</label><input name="name" required maxlength="32" minlength="1" value="${esc(state.profile.name)}"></div><div class="form-actions"><button class="btn btn-primary">Salvar perfil</button></div></form><div class="divider"></div>${state.user?'<button class="btn btn-danger" data-action="logout">Sair da conta</button>':'<button class="btn btn-primary" data-action="auth">Entrar ou criar conta</button>'}</section></div><section class="card section-gap">${cardHead('Resumo da jornada','Contagens baseadas nos seus registros.')}<div class="grid grid-3"><div><div class="kpi">${getTasks().filter(x=>x.completed_at).length}</div><small class="muted">Tarefas concluídas</small></div><div><div class="kpi">${state.study.length}</div><small class="muted">Sessões de estudo</small></div><div><div class="kpi">${state.workouts.length}</div><small class="muted">Atividades físicas</small></div></div></section>`}
function renderSettings(){const p=state.settings;return `${head('Configurações','Personalize os sons, lembretes e sua experiência.')}<div class="grid grid-2"><section class="card">${cardHead('Sons e acessibilidade','Os efeitos são sintetizados pelo navegador.')}<div class="setting-row"><div><b>Efeitos sonoros</b><small>Feedback em ações importantes.</small></div><input type="checkbox" class="switch" data-setting="sounds" ${p.sounds?'checked':''}></div><div class="setting-row"><div><b>Volume dos efeitos</b><small>Volume entre 0 e 100%.</small></div><input type="range" min="0" max="1" step=".05" value="${p.volume}" data-setting="volume"></div><div class="setting-row"><div><b>Movimentos reduzidos</b><small>Respeita a preferência do sistema operacional.</small></div><input type="checkbox" class="switch" data-setting="motion" ${p.motion?'checked':''}></div><button class="btn btn-outline" data-action="test-sound">▶ Testar som</button></section><section class="card">${cardHead('Lembretes','Na página aberta, o aplicativo verifica os prazos periodicamente.')}<div class="setting-row"><div><b>Lembretes no aplicativo</b><small>Funciona enquanto o LEVEL UP estiver aberto; não agenda lembretes com o navegador totalmente fechado.</small></div><input type="checkbox" class="switch" data-setting="reminders" ${p.reminders?'checked':''}></div><div class="field"><label>Antecedência padrão</label><select data-setting="reminderMinutes">${[[0,'No horário exato'],[5,'5 minutos antes'],[10,'10 minutos antes'],[15,'15 minutos antes'],[30,'30 minutos antes'],[60,'1 hora antes'],[1440,'1 dia antes'],[-1,'Sem lembretes']].map(([v,l])=>`<option value="${v}" ${+p.reminderMinutes===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="setting-row"><div><b>Notificações do navegador</b><small>${!('Notification'in window)?'Este navegador não oferece notificações.':Notification.permission==='granted'?'Permissão autorizada.':Notification.permission==='denied'?'Bloqueadas: habilite nas configurações do site no navegador.':'Ainda precisam de permissão.'}</small></div><button class="btn btn-outline" data-action="request-notifications">${('Notification'in window&&Notification.permission==='granted')?'Autorizadas':'Solicitar permissão'}</button></div><button class="btn btn-outline" data-action="test-notification">Testar notificação</button><div class="field"><label>Silêncio começa</label><input type="time" data-setting="quietStart" value="${esc(p.quietStart||'22:00')}"></div><div class="field" style="margin-top:10px"><label>Silêncio termina</label><input type="time" data-setting="quietEnd" value="${esc(p.quietEnd||'08:00')}"></div></section><section class="card">${cardHead('Perfil e conta','Gerencie seu nome ou sua sessão.')}<div class="setting-row"><div><b>Nome de jogador</b><small>${esc(state.profile.name)}</small></div><button class="btn btn-outline" data-route="perfil">Editar perfil</button></div><div class="setting-row"><div><b>Autenticação</b><small>${state.user?esc(state.user.email):'Não conectado'}</small></div><button class="btn btn-outline" data-action="${state.user?'logout':'auth'}">${state.user?'Sair':'Entrar'}</button></div></section><section class="card">${cardHead('Dados e sincronização','O modo local é apenas para experimentar a interface.')}<p class="muted small">${hasSupabase?'Chave pública configurada. Seus dados podem sincronizar após executar o SQL.':'Supabase ainda não configurado. O modo local salva no navegador deste dispositivo; não é autenticação real nem sincroniza entre dispositivos.'}</p><div class="divider"></div><button class="btn btn-outline" data-action="test-connection">Testar conexão Supabase</button></section></div>`}
function render(){const fn=({inicio:renderHome,tarefas:renderTasks,calendario:renderCalendar,fisico:renderFitness,estudos:renderStudies,habitos:renderHabits,evolucao:renderEvolution,missoes:renderMissions,conquistas:renderAchievements,recompensas:renderRewards,perfil:renderProfile,configuracoes:renderSettings})[state.route]||renderHome;$('#view').innerHTML=fn();$('#page-title').textContent=routes[state.route];$$('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===state.route));updateHeader()}
function authModal(mode='login'){const login=mode==='login';openModal(`<div class="eyebrow">PLAYER IDENTITY</div><h2>${login?'Entrar no LEVEL UP':mode==='signup'?'Criar conta':'Recuperar senha'}</h2><p>${hasSupabase?'Entre para sincronizar seu progresso com segurança.':'Para autenticação real, configure a chave publicável do Supabase em assets/js/config.js.'}</p><div class="auth-tabs"><button class="btn ${login?'btn-primary':'btn-outline'}" data-action="auth-mode" data-value="login">Entrar</button><button class="btn ${mode==='signup'?'btn-primary':'btn-outline'}" data-action="auth-mode" data-value="signup">Criar conta</button></div><form id="auth-form" class="form-grid"><div class="field full"><label>E-mail</label><input name="email" type="email" required autocomplete="email" placeholder="voce@exemplo.com"></div>${mode!=='recovery'?`<div class="field full"><label>Senha</label><div style="display:flex;gap:7px"><input style="flex:1" id="auth-password" name="password" type="password" required minlength="6" autocomplete="${login?'current-password':'new-password'}" placeholder="Mínimo de 6 caracteres"><button class="btn btn-outline" type="button" data-action="toggle-password">Ver</button></div></div>`:''}${mode==='signup'?`<div class="field full"><label>Confirmar senha</label><input name="confirm" type="password" required minlength="6" autocomplete="new-password"></div>`:''}<div class="field full"><button class="btn btn-primary" style="width:100%" ${!hasSupabase?'title="Configure a chave do Supabase primeiro"':''}>${login?'Entrar':mode==='signup'?'Criar minha conta':'Enviar link de recuperação'}</button></div></form><button class="btn btn-quiet" data-action="auth-mode" data-value="recovery">Esqueci minha senha</button><p class="small muted">Nunca armazenamos senhas próprias. O Supabase Auth processa credenciais.</p>`)}
async function onAuthSubmit(form){if(!hasSupabase)throw Error('Configure a chave publicável do Supabase em assets/js/config.js antes de usar autenticação.');const fd=new FormData(form),email=String(fd.get('email')||'').trim(),password=String(fd.get('password')||''),confirm=String(fd.get('confirm')||'');const title=$('#modal-content h2')?.textContent||'';if(title.includes('Recuperar')){const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname+'#perfil'});if(error)throw error;closeModal();toast('Se o e-mail existir, o Supabase enviará instruções conforme sua configuração.','success');return}
if(title.includes('Criar conta')){if(password!==confirm)throw Error('As senhas não coincidem.');const {data,error}=await sb.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname+'#inicio'}});if(error)throw error;if(data.session){await sb.rpc('lu_bootstrap_profile',{p_player_name:email.split('@')[0]});closeModal();toast('Conta criada e sessão iniciada.','success')}else{closeModal();toast('Cadastro enviado. Se a confirmação estiver ativa, verifique seu e-mail.','success')}return}
const {error}=await sb.auth.signInWithPassword({email,password});if(error)throw error;closeModal();toast('Login realizado.','success');sound('success');await refresh()}
function taskSaveError(err){
 const code=String(err?.code||''),message=String(err?.message||''),details=String(err?.details||'');
 // Keep technical details in DevTools without logging credentials or session data.
 console.error('[LEVEL UP] Falha ao salvar tarefa', {code,message,details,hint:err?.hint||''});
 if(code==='42501'||/row-level security|RLS|permission denied/i.test(message))return 'O banco recusou o cadastro por segurança (RLS). Entre novamente e confira se as políticas da tabela lu_tasks permitem inserir tarefas do próprio usuário.';
 if(code==='PGRST204'||code==='PGRST205'||code==='42703'||/column .* does not exist|schema cache/i.test(message+' '+details))return 'O banco está com as migrações incompletas: faltam colunas usadas por tarefas e lembretes. No Supabase, execute supabase/002_reminders.sql e tente novamente. Seus dados não foram apagados.';
 if(code==='401'||/JWT expired|invalid JWT|not authenticated/i.test(message))return 'Sua sessão pode ter expirado. Entre novamente e tente salvar a tarefa.';
 if(/Failed to fetch|NetworkError|fetch failed/i.test(message))return 'Não foi possível conectar ao Supabase. Verifique a internet, a URL do projeto e se o navegador consegue acessar o serviço.';
 return message||'Não foi possível salvar a tarefa. Confira a conexão e tente novamente.';
}
async function handleTaskForm(form){const fd=new FormData(form),title=String(fd.get('title')||'').trim();if(!title)throw Error('Informe o nome da tarefa.');const rawCategory=String(fd.get('category')||'Geral').trim();const categoryMap={'Geral':'general','Inglês':'english','Matemática':'Matemática','Programação':'Programação','Banco de Dados':'Banco de Dados','Português':'Português','Estudos':'study','Atividade física':'fitness','Hábito':'habit','Pessoal':'personal'};const dueDate=String(fd.get('due_date')||''),dueTime=String(fd.get('due_time')||''),dateOnly=!!dueDate&&!dueTime;let dueAt=null;if(dueDate){const [y,m,d]=dueDate.split('-').map(Number);const [hh,mm]=dueTime?dueTime.split(':').map(Number):[23,59];dueAt=new Date(y,m-1,d,hh,mm,0,0).toISOString()}const row={title,description:String(fd.get('description')||''),category:categoryMap[rawCategory]||rawCategory,spent_minutes:fd.get('spent_minutes')!==''&&fd.get('spent_minutes')!=null?Number(fd.get('spent_minutes')):null,priority:String(fd.get('priority')),due_at:dueAt,due_date_only:dateOnly,reminder_minutes:Number(fd.get('reminder_minutes')??state.settings.reminderMinutes),reminder_sent_at:null,estimated_minutes:fd.get('estimated_minutes')?Number(fd.get('estimated_minutes')):null};const taskId=fd.get('id');state.taskSchemaWarning=null;if(taskId){await updateRow('lu_tasks',taskId,{...row,updated_at:new Date().toISOString()})}else await insert('lu_tasks',row);const schemaWarning=state.taskSchemaWarning;closeModal();toast(taskId?'Tarefa atualizada.':'Tarefa criada.','success');if(schemaWarning?.length)toast('A tarefa foi salva, mas alguns campos opcionais não existem no banco ('+schemaWarning.join(', ')+'). Execute supabase/003_task_creation_compat.sql para habilitá-los.','warn',10000);sound('success');await refresh()}
async function handleForm(form){if(form.id==='task-form')return handleTaskForm(form);if(form.id==='event-form'){const fd=new FormData(form),date=String(fd.get('starts_date')),time=String(fd.get('starts_time')||''),[y,m,d]=date.split('-').map(Number),[hh,mm]=time?time.split(':').map(Number):[23,59];await insert('lu_events',{title:String(fd.get('title')).trim(),category:String(fd.get('category')),starts_at:new Date(y,m-1,d,hh,mm).toISOString(),starts_date_only:!time,reminder_minutes:Number(fd.get('reminder_minutes')??state.settings.reminderMinutes),reminder_sent_at:null,notes:String(fd.get('notes')||'')});closeModal();toast('Atividade agendada.','success');await refresh();return}
if(form.id==='workout-form'){const fd=new FormData(form),item=await insert('lu_workouts',{modality:String(fd.get('modality')),duration_minutes:Number(fd.get('duration_minutes')),activity_date:String(fd.get('activity_date')),notes:String(fd.get('notes')||'')});const xp=await award('workout',item.id,'Atividade física registrada',10);closeModal();toast(`Atividade salva${xp?` · +${xp} XP`:''}.`,'success');sound('success');await refresh();return}
if(form.id==='study-form'){const fd=new FormData(form),item=await insert('lu_study_sessions',{subject:String(fd.get('subject')).trim(),duration_minutes:Number(fd.get('duration_minutes')),difficulty:String(fd.get('difficulty')||''),learned:String(fd.get('learned')||'')});const xp=await award('study',item.id,'Sessão de estudo registrada',10);closeModal();toast(`Sessão salva${xp?` · +${xp} XP`:''}.`,'success');sound('success');await refresh();return}
if(form.id==='habit-form'){const fd=new FormData(form);await insert('lu_habits',{title:String(fd.get('title')).trim(),frequency:String(fd.get('frequency')),days:[0,1,2,3,4,5,6],archived:false});closeModal();toast('Hábito criado.','success');await refresh();return}
if(form.id==='profile-form'){await saveProfile(String(new FormData(form).get('name')).trim());toast('Perfil atualizado.','success');render();return}
if(form.id==='auth-form')return onAuthSubmit(form)}
async function onAction(el){const a=el.dataset.action,idv=el.dataset.id,val=el.dataset.value;
if(el.dataset.route){setRoute(el.dataset.route);return}
switch(a){
case 'new-task':taskForm();break;case 'close-modal':closeModal();break;case 'edit-task':{const t=getTasks().find(x=>x.id===idv);if(t)taskForm(t);break}
case 'delete-task':if(confirm('Excluir esta tarefa? Esta ação não pode ser desfeita.')){await deleteRow('lu_tasks',idv);toast('Tarefa excluída.','success');await refresh()}break;
case 'complete-task':if(el.checked){const xp=await completeTask(idv);toast(xp?`Tarefa concluída · +${xp} XP!`:'Tarefa já concluída.','success');sound('success');await refresh()}break;
case 'task-filter':state.taskFilter=val;render();break;case 'new-event':eventForm();break;case 'cal-mode':state.calMode=val;render();break;case 'cal-prev':state.calDate.setDate(state.calDate.getDate()+(state.calMode==='month'?-30:state.calMode==='week'?-7:-1));render();break;case 'cal-next':state.calDate.setDate(state.calDate.getDate()+(state.calMode==='month'?30:state.calMode==='week'?7:1));render();break;case 'cal-today':state.calDate=new Date();render();break;case 'calendar-day':state.calDate=new Date(el.dataset.date);state.calMode='day';render();break;
case 'new-workout':workoutForm();break;case 'new-study':studyForm();break;case 'new-habit':habitForm();break;
case 'habit-toggle':{const h=state.habits.find(x=>x.id===idv),done=state.habitLogs.some(x=>x.habit_id===idv&&x.log_date===today());if(done){toast('Este hábito já está registrado hoje.','warn');render();break}const item=await insert('lu_habit_logs',{habit_id:idv,log_date:today()});const xp=await award('habit',item.id,'Hábito concluído',5);toast(`Hábito registrado${xp?` · +${xp} XP`:''}.`,'success');await refresh();break}
case 'habit-archive':await updateRow('lu_habits',idv,{archived:true});toast('Hábito arquivado.','success');await refresh();break;
case 'auth':authModal();break;case 'auth-mode':authModal(val);break;case 'toggle-password':{const p=$('#auth-password');if(p){p.type=p.type==='password'?'text':'password';el.textContent=p.type==='password'?'Ver':'Ocultar'}break}
case 'logout':if(state.user&&sb){const {error}=await sb.auth.signOut();if(error)throw error;state.user=null;state.tasks=[];state.events=[];state.habits=[];state.habitLogs=[];state.workouts=[];state.study=[];state.xp=0;state.xpLog=[];state.profile={name:'Jogador'};toast('Você saiu da conta.','success');await refresh()}else toast('Você está no modo local.','info');break;
case 'test-sound':sound('level');toast('Teste de som acionado. Se não ouviu, clique novamente após interagir com a página.','success');break;
case 'test-notification':if(!('Notification'in window)){toast('Este navegador não oferece notificações.','error');break}if(Notification.permission!=='granted'){toast('Primeiro, autorize as notificações do navegador.','warn');break}try{const n=new Notification('LEVEL UP — Teste de notificação',{body:'As notificações visuais estão configuradas.'});n.onclick=()=>{window.focus();n.close()};if(state.settings.sounds)sound('reminder');toast('Notificação de teste enviada.','success')}catch(err){toast('Não foi possível mostrar a notificação: '+err.message,'error')}break;
case 'request-notifications':if(!('Notification'in window)){toast('Este navegador não oferece a API de notificações.','error');break}if(Notification.permission==='granted'){state.settings.browserNotifications=true;await persistSettings();toast('Notificações já estão permitidas.','success')}else{const permission=await Notification.requestPermission();state.settings.browserNotifications=permission==='granted';await persistSettings();toast(permission==='granted'?'Permissão concedida.':'Permissão não concedida.',permission==='granted'?'success':'warn')}render();break;
case 'test-connection':if(!hasSupabase){toast('Preencha a chave publicável em assets/js/config.js.','warn');break}try{const {error}=await sb.auth.getSession();if(error)throw error;toast('Cliente Supabase respondeu. Isso não substitui testar as tabelas após executar o SQL.','success')}catch(e){toast(e.message,'error')}break;
}}
document.addEventListener('click',async e=>{const route=e.target.closest('[data-route]');const action=e.target.closest('[data-action]');try{if(route){e.preventDefault();setRoute(route.dataset.route);return}if(action){e.preventDefault();await onAction(action)}}catch(err){toast(err.message||'Ocorreu um erro.','error',6000)}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['event-form','workout-form','study-form','habit-form','profile-form','auth-form'].includes(f.id))return;e.preventDefault();const submit=f.querySelector('[type=submit],button:not([type])');if(submit){submit.disabled=true;submit.dataset.old=submit.textContent;submit.textContent='Salvando…'}try{await handleForm(f)}catch(err){toast(f.id==='task-form'?taskSaveError(err):(err.message||'Não foi possível salvar. Tente novamente.'),'error',8000)}finally{if(submit&&submit.isConnected){submit.disabled=false;submit.textContent=submit.dataset.old||'Salvar'}}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='evolution-period'||el.id==='evolution-category'||el.id==='evolution-start'||el.id==='evolution-end'){render();return}if(el.dataset.setting){const key=el.dataset.setting;let value=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.type==='number'?Number(el.value):el.value;if(key==='reminderMinutes')value=Number(value);state.settings[key]=value;try{await persistSettings();if(key==='sounds')toast(value?'Sons ativados.':'Sons desativados.','success');if(key==='volume')sound('click');}catch(err){toast('Não foi possível salvar a configuração: '+err.message,'error')}return}if(el.matches('[data-action="complete-task"]')&&!el.checked)return});
$('#auth-button').addEventListener('click',()=>authModal());$('#user-chip').addEventListener('click',()=>setRoute('perfil'));$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#sidebar-collapse').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#modal-close').addEventListener('click',closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});$('#sound-toggle').addEventListener('click',async()=>{state.settings.sounds=!state.settings.sounds;try{await persistSettings();toast(state.settings.sounds?'Sons ativados.':'Sons desativados.','success');if(state.settings.sounds)sound('success')}catch(e){toast(e.message,'error')}render()});
$('#notification-toggle').addEventListener('click',()=>{const old=$('#notice-panel');if(old){old.remove();return}const p=document.createElement('section');p.className='notice-panel';p.id='notice-panel';p.innerHTML=`<div class="row-between"><h3>Notificações</h3><button class="icon-button" id="close-notices">×</button></div>${state.notices.length?state.notices.map(n=>`<div class="notice-item"><b>${esc(n.title)}</b><small>${esc(n.body)} · ${dateLabel(n.at)}</small></div>`).join(''):'<div class="empty">Nenhuma notificação ainda.</div>'}`;document.body.append(p);$('#close-notices').onclick=()=>p.remove();$('#notice-dot').classList.add('hidden')});
function checkReminders(){
 if(!state.settings.reminders)return;
 const now=Date.now(),items=[...getTasks().filter(t=>!t.completed_at&&t.due_at).map(t=>({...t,starts_at:t.due_at,kind:'task'})),...state.events.filter(e=>!e.completed_at&&e.starts_at).map(e=>({...e,kind:'event'}))];
 for(const x of items){if(x.kind==='task'&&x.due_date_only||x.kind==='event'&&x.starts_date_only)continue;const minutes=Number(x.reminder_minutes??state.settings.reminderMinutes);if(minutes<0)continue;const due=new Date(x.starts_at).getTime(),fireAt=due-minutes*60000;const key=`levelup.reminder.v2.${x.kind}.${x.id}.${x.starts_at}.${minutes}`;if(localStorage.getItem(key))continue;if(now<fireAt||now-fireAt>180000)continue;localStorage.setItem(key,new Date().toISOString());const clock=new Date(x.starts_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});const body=minutes===0?`Está na hora de ${x.title}! Horário: ${clock}`:`Lembrete: ${x.title}. Agendada para ${clock}.`;addNotice('LEVEL UP — Lembrete de atividade',body);toast(body,'warn',10000);if(state.settings.sounds)sound('reminder');if(state.settings.browserNotifications&&'Notification'in window&&Notification.permission==='granted'){try{const n=new Notification('LEVEL UP — Lembrete de atividade',{body,tag:key,renotify:false,data:{id:x.id,kind:x.kind}});n.onclick=()=>{window.focus();setRoute(x.kind==='task'?'tarefas':'calendario');n.close()}}catch{}}}
}
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(routes[r]&&r!==state.route)setRoute(r)});
async function boot(){document.documentElement.classList.toggle('reduce-motion',!state.settings.motion);if(!hasSupabase){await loadData();updateHeader();render();toast('Modo local ativo. Configure a chave Supabase para login e sincronização reais.','warn',6500)}else{try{const {data:{session}}=await sb.auth.getSession();state.user=session?.user||null;if(state.user){await sb.rpc('lu_bootstrap_profile',{p_player_name:state.user.email?.split('@')[0]||'Jogador'});await loadData()}else await loadData();updateHeader();render()}catch(e){toast('Falha ao iniciar sessão: '+e.message,'error');render()}sb.auth.onAuthStateChange(async(_event,session)=>{state.user=session?.user||null;if(state.user){try{await sb.rpc('lu_bootstrap_profile',{p_player_name:state.user.email?.split('@')[0]||'Jogador'})}catch{} }await refresh()})}
const r=location.hash.slice(1);if(routes[r])setRoute(r);setInterval(checkReminders,5000);checkReminders()}
boot();
